protocol_source:
// Package protocol defines harness provider protocol v1: an MCP server
// that speaks harness's own capability model, so harness can use it with
// no mapping (type = "harness"). It is the providers.Provider interface
// expressed as MCP tools:
//
//   - harness_provider_info (handshake): {protocol, name, capabilities, refresh}
//   - one tool per capability, named by replacing "." with "_"
//     (code.symbol_search -> code_symbol_search), taking the request
//     fields {query, path, limit, package, version, type} and returning
//     {items, truncated, summary, text}, items in harness's item fields
//   - harness_refresh {full, changed} -> {skipped, detail}, when the
//     provider keeps an index
//
// Serve exposes any providers.Provider this way; New is the harness side.
// See docs/provider-protocol.md.
package protocol

import (
	"strings"

	"harness/internal/providers"
)

// Version is the protocol identifier a provider reports in its handshake.
// Harness accepts any "harness-provider/1.x"; a new major version is not
// compatible.
const Version = "harness-provider/1"

// Tool names outside the capability tools.
const (
	InfoTool    = "harness_provider_info"
	RefreshTool = "harness_refresh"
)

// ToolFor returns the tool that serves a capability.
func ToolFor(c providers.Capability) string { return strings.ReplaceAll(string(c), ".", "_") }

// Info is the handshake response.
type Info struct {
	Protocol     string       `json:"protocol"`
	Name         string       `json:"name"`
	Capabilities []Capability `json:"capabilities"`
	// Refresh reports that the provider keeps an index harness should
	// refresh after syncs (harness_refresh).
	Refresh bool `json:"refresh,omitempty"`
}

// Capability describes one served capability.
type Capability struct {
	Capability string `json:"capability"`
	Freshness  string `json:"freshness,omitempty"` // live (default) or indexed
	Cost       string `json:"cost,omitempty"`      // low, medium (default), high
	Latency    string `json:"latency,omitempty"`
	Evidence   string `json:"evidence,omitempty"` // exact or inferred (default by capability)
}

// Request is a capability tool's input.
type Request struct {
	Query   string `json:"query,omitempty"`
	Path    string `json:"path,omitempty"`
	Limit   int    `json:"limit,omitempty"`
	Target  string `json:"target,omitempty"` // code.flow destination
	Budget  int    `json:"budget,omitempty"` // code.context size in bytes
	Package string `json:"package,omitempty"`
	Version string `json:"version,omitempty"`
	Type    string `json:"type,omitempty"`
}

// Response is a capability tool's output.
type Response struct {
	Items     []providers.Item `json:"items"`
	Truncated bool             `json:"truncated,omitempty"`
	Summary   map[string]any   `json:"summary,omitempty"`
	Text      string           `json:"text,omitempty"`
}

// RefreshRequest is harness_refresh's input.
type RefreshRequest struct {
	Full    bool     `json:"full,omitempty"`
	Changed []string `json:"changed,omitempty"`
}

// RefreshResponse is harness_refresh's output.
type RefreshResponse struct {
	Skipped bool   `json:"skipped,omitempty"`
	Detail  string `json:"detail,omitempty"`
}

// Compatible reports whether a handshake's protocol is v1.
func Compatible(protocol string) bool {
	return protocol == Version || strings.HasPrefix(protocol, Version+".")
}

capability_source:
// Package providers defines the provider-neutral capability model the
// harness uses to consult downstream sources (other MCP servers today,
// native indexes later) and a registry that routes capability requests to
// every provider offering them, isolating failures.
//
// Nothing here knows about a specific provider; adapters live in
// sub-packages.
package providers

import (
	"context"
	"errors"
	"fmt"
	"path/filepath"
	"slices"
	"sort"
	"strings"
	"sync"
	"time"
)

// Capability names a kind of question a provider can answer.
type Capability string

const (
	// SymbolSearch finds code definitions (functions, types, ...) by name
	// or concept.
	SymbolSearch Capability = "code.symbol_search"
	// TextSearch finds occurrences of text in source files.
	TextSearch Capability = "code.text_search"
	// FileSearch finds files by name or path.
	FileSearch Capability = "code.file_search"
	// Overview summarizes project structure.
	Overview Capability = "project.overview"
	// Callers finds the code that calls a named symbol (query = name).
	Callers Capability = "code.callers"
	// References finds every use of a named symbol: calls, type uses,
	// implementations, reads/writes (query = name).
	References Capability = "code.references"
	// Context returns the code units relevant to a task (query = task
	// text), within Budget: definitions with bodies or drill-down
	// references, plus related callers and tests.
	Context Capability = "code.context"
	// Impact returns what a change to a symbol or file affects (query =
	// symbol name or path): dependent symbols, files and tests, with Depth
	// = hops from the changed code.
	Impact Capability = "code.impact"
	// Flow returns a call path from the symbol in Query to the one in
	// Target, one item per hop in order (Depth = hop index).
	Flow Capability = "code.flow"

	// Package capabilities describe external dependencies (e.g. NuGet
	// packages) rather than the project's own code.

	// PackageSearch finds packages by name or described functionality.
	PackageSearch Capability = "package.search"
	// PackageInfo describes one package version (metadata, dependencies).
	PackageInfo Capability = "package.info"
	// PackageTypes lists the public types of a package version.
	PackageTypes Capability = "package.types"
	// PackageTypeDefinition returns the public API of one type.
	PackageTypeDefinition Capability = "package.type_definition"

	// Architecture capabilities (HAR-0141) give the evidence architecture
	// findings rest on. Units are the provider's own (project, package,
	// module, folder or file); each item says where the evidence is, the
	// other end of a relation in Related, and how sure the provider is in
	// Confidence.

	// ArchDependencies lists the dependencies between units (query: a unit
	// to start from, or empty for all): Name depends on Related.Name, Path
	// and StartLine where that is stated (a reference, an import).
	ArchDependencies Capability = "arch.dependencies"
	// ArchCycles lists the circles of dependencies: one item per circle,
	// its units in Members, Path a place showing one of its edges.
	ArchCycles Capability = "arch.cycles"
	// ArchChangeCoupling lists the files that change together with the
	// file in Query (co-change: Path the partner, Count the commits they
	// share, Confidence the share of the file's commits), or with no query
	// the files changed most (hotspots: Count the commits).
	ArchChangeCoupling Capability = "arch.change_coupling"
	// ArchDuplicates lists code that repeats other code (clones and near
	// copies): the item is one copy, Related the other, Confidence the
	// similarity.
	ArchDuplicates Capability = "arch.duplicates"
	// ArchDeadCode lists code nothing in the project uses (symbols or
	// units), Confidence how sure (dynamic uses, reflection and outside
	// callers are invisible to static reading).
	ArchDeadCode Capability = "arch.dead_code"
)

// ArchCapabilities are the architecture capabilities, in contract order.
var ArchCapabilities = []Capability{ArchDependencies, ArchCycles, ArchChangeCoupling, ArchDuplicates, ArchDeadCode}

// IsPackage reports whether c describes external packages.
func (c Capability) IsPackage() bool { return strings.HasPrefix(string(c), "package.") }

// IsArch reports whether c gives architecture evidence.
func (c Capability) IsArch() bool { return strings.HasPrefix(string(c), "arch.") }

// Hint is a coarse, comparable estimate used for routing and display.
type Hint string

const (
	Low    Hint = "low"
	Medium Hint = "medium"
	High   Hint = "high"
)

// Freshness says how current a provider's answers are.
type Freshness string

const (
	// Live answers reflect the working tree at call time.
	Live Freshness = "live"
	// Indexed answers reflect the provider's last index of the project.
	Indexed Freshness = "indexed"
)

// Scope says what a provider's answers cover.
type Scope string

const (
	ScopeProject Scope = "project"
	// ScopeExternal answers come from outside the project (package feeds).
	ScopeExternal Scope = "external"
)

// Evidence says how certain a capability's answers are.
type Evidence string

const (
	// Exact answers are facts: literal matches, compiler-resolved
	// relations.
	Exact Evidence = "exact"
	// Inferred answers are heuristics: name-based relations, relevance
	// ranking.
	Inferred Evidence = "inferred"
)

// CapabilityInfo describes one capability offered by one provider.
type CapabilityInfo struct {
	Capability Capability `json:"capability"`
	Provider   string     `json:"provider"`
	Cost       Hint       `json:"cost"`
	Latency    Hint       `json:"latency"`
	Freshness  Freshness  `json:"freshness"`
	Scope      Scope      `json:"scope"`
	// Evidence is empty when the provider does not say; see DefaultEvidence.
	Evidence Evidence `json:"evidence,omitempty"`
}

// DefaultEvidence is a capability's evidence when its provider does not
// declare one: literal text and file-name matches are exact, relations
// and relevance searches inferred.
func DefaultEvidence(c Capability) Evidence {
	switch c {
	case TextSearch, FileSearch, ArchChangeCoupling: // co-change counts are history's facts
		return Exact
	}
	return Inferred
}

// EvidenceOf is the declared evidence, or the default.
func (ci CapabilityInfo) EvidenceOf() Evidence {
	if ci.Evidence != "" {
		return ci.Evidence
	}
	return DefaultEvidence(ci.Capability)
}

// Request asks for one capability.
type Request struct {
	Capability Capability
	// Query is the search text (plain text, not a regex) or empty for
	// Overview.
	Query string
	// Path optionally restricts results to a path prefix relative to the
	// project root.
	Path string
	// Limit caps the number of items (0: provider default).
	Limit int
	// Target is the destination symbol for Flow.
	Target string
	// Budget caps a Context answer in bytes of item text (0: provider
	// default).
	Budget int
	// Package capabilities: package id, optional version (empty: latest)
	// and type name.
	Package string
	Version string
	Type    string
}

// Covers reports whether file (relative to the project root) is under the
// request's Path; every file is without one.
func (r Request) Covers(file string) bool {
	if r.Path == "" {
		return true
	}
	prefix := strings.TrimSuffix(filepath.ToSlash(r.Path), "/")
	return file == prefix || strings.HasPrefix(file, prefix+"/")
}

// ItemKind classifies result items.
type ItemKind string

const (
	KindSymbol  ItemKind = "symbol"
	KindMatch   ItemKind = "match"
	KindFile    ItemKind = "file"
	KindPackage ItemKind = "package"
	// KindRelation is a relation between units (a dependency, a cycle).
	KindRelation ItemKind = "relation"
)

// Ref points at the other end of a relation: a unit or symbol, and where
// it is when known.
type Ref struct {
	Name      string `json:"name,omitempty"`
	Path      string `json:"path,omitempty"` // relative to the project root
	StartLine int    `json:"start_line,omitempty"`
}

// Item is one normalized result with provenance.
type Item struct {
	Kind          ItemKind `json:"kind"`
	Name          string   `json:"name,omitempty"`
	QualifiedName string   `json:"qualified_name,omitempty"`
	Label         string   `json:"label,omitempty"` // provider-specific type, e.g. "Function"
	Path          string   `json:"path,omitempty"`  // relative to the project root
	StartLine     int      `json:"start_line,omitempty"`
	EndLine       int      `json:"end_line,omitempty"`
	Snippet       string   `json:"snippet,omitempty"`
	Score         float64  `json:"score,omitempty"` // provider-relative; higher is better
	// Depth is the distance from the query: impact hops, or the position
	// in a flow path (0 = the query symbol).
	Depth int `json:"depth,omitempty"`
	// Architecture evidence (arch.*): the other end of a relation (the
	// unit depended on, the other copy, the co-change partner's file), a
	// cycle's units in order, a count (shared commits, references) and the
	// provider's confidence, 0..1 (0: not stated).
	Related    *Ref     `json:"related,omitempty"`
	Members    []string `json:"members,omitempty"`
	Count      int      `json:"count,omitempty"`
	Confidence float64  `json:"confidence,omitempty"`
	// Provenance: which provider and downstream tool produced the item.
	Provider string `json:"provider"`
	Tool     string `json:"tool"`
}

// Result is one provider's answer to a Request.
type Result struct {
	Provider   string
	Capability Capability
	Items      []Item
	// Summary carries structured non-list answers (Overview).
	Summary map[string]any
	// Text carries answers that are documents rather than lists (package
	// info, type definitions).
	Text string
	// Truncated reports that the provider had more results than returned.
	Truncated bool
	// Observations for observability; filled in by the registry.
	Latency  time.Duration
	Bytes    int  // size of the provider's raw response
	TimedOut bool // the call ran out of time (Err says so too)
	Err      error
}

// State is a provider's health state.
type State string

const (
	// Idle: configured but not started yet (started on first use).
	Idle State = "idle"
	// Ready: running and able to answer.
	Ready State = "ready"
	// Degraded: running, but some answers will be missing (e.g. the
	// project is not indexed).
	Degraded State = "degraded"
	// Unavailable: cannot be used (failed to start, crashed repeatedly).
	Unavailable State = "unavailable"
)

// Health describes a provider's state. Fix is set when action helps.
type Health struct {
	State  State  `json:"state"`
	Detail string `json:"detail,omitempty"`
	Fix    string `json:"fix,omitempty"`
}

// Provider is implemented by each adapter.
type Provider interface {
	Name() string
	Capabilities() []CapabilityInfo
	// Health reports state. With probe it may start the provider to check;
	// without, it must not have side effects.
	Health(ctx context.Context, probe bool) Health
	// Do answers a request for one of the provider's capabilities. Bytes in
	// the returned Result should be set to the raw response size.
	Do(ctx context.Context, req Request) (Result, error)
	Close() error
}

// Error is a provider failure wrapped with its origin.
type Error struct {
	Provider string
	Tool     string
	Message  string
	Hint     string
}

func (e *Error) Error() string {
	s := fmt.Sprintf("%s: %s", e.Provider, e.Message)
	if e.Tool != "" {
		s = fmt.Sprintf("%s (%s): %s", e.Provider, e.Tool, e.Message)
	}
	if e.Hint != "" {
		s += " — " + e.Hint
	}
	return s
}

// ErrUnsupported is returned for a capability a provider does not offer.
var ErrUnsupported = errors.New("capability not supported by provider")

// ErrNotIndexed is wrapped by errors of an indexed provider that has no
// index of this checkout (e.g. a linked worktree): a degraded state the
// answer notes, not a failure; live providers still answer.
var ErrNotIndexed = errors.New("not indexed by the provider")

// Observer receives one record per provider call (for persistence).
type Observer func(Result, Request)

// Registry holds configured providers.
type Registry struct {
	mu        sync.Mutex
	providers []Provider
	timeout   time.Duration
	observe   Observer
	skipPath  func(path string) bool
	noContext map[string]bool
}

// NewRegistry creates a registry. timeout bounds each provider call
// (0: 30s).
func NewRegistry(timeout time.Duration) *Registry {
	if timeout <= 0 {
		timeout = 30 * time.Second
	}
	return &Registry{timeout: timeout}
}

// Register adds a provider.
func (r *Registry) Register(p Provider) {
	r.mu.Lock()
	defer r.mu.Unlock()
	r.providers = append(r.providers, p)
}

// SetObserver installs a callback invoked after every provider call.
func (r *Registry) SetObserver(o Observer) {
	r.mu.Lock()
	defer r.mu.Unlock()
	r.observe = o
}

// SetPathFilter drops, from every provider's results, items whose path
// skip reports true (e.g. files inside a nested git worktree, which would
// otherwise come back once per checkout).
func (r *Registry) SetPathFilter(skip func(path string) bool) {
	r.mu.Lock()
	defer r.mu.Unlock()
	r.skipPath = skip
}

// ExcludeFromContext keeps assembled answers (get_context) from asking the
// named provider; direct searches still do.
func (r *Registry) ExcludeFromContext(name string) {
	r.mu.Lock()
	defer r.mu.Unlock()
	if r.noContext == nil {
		r.noContext = map[string]bool{}
	}
	r.noContext[name] = true
}

// InContext reports whether assembled answers may ask the provider.
func (r *Registry) InContext(name string) bool {
	r.mu.Lock()
	defer r.mu.Unlock()
	return !r.noContext[name]
}

// Providers returns the registered providers in registration order.
func (r *Registry) Providers() []Provider {
	r.mu.Lock()
	defer r.mu.Unlock()
	return append([]Provider(nil), r.providers...)
}

// Capabilities lists every capability/provider pair, sorted.
func (r *Registry) Capabilities() []CapabilityInfo {
	var out []CapabilityInfo
	for _, p := range r.Providers() {
		out = append(out, p.Capabilities()...)
	}
	sort.Slice(out, func(i, j int) bool {
		if out[i].Capability != out[j].Capability {
			return out[i].Capability < out[j].Capability
		}
		return out[i].Provider < out[j].Provider
	})
	return out
}

// For returns the providers offering c.
func (r *Registry) For(c Capability) []Provider {
	var out []Provider
	for _, p := range r.Providers() {
		for _, ci := range p.Capabilities() {
			if ci.Capability == c {
				out = append(out, p)
				break
			}
		}
	}
	return out
}

// Call sends req to every provider offering its capability, concurrently.
// Each provider gets its own timeout; a failure or panic in one provider is
// reported in its Result and never affects the others. Results are returned
// in registration order.
func (r *Registry) Call(ctx context.Context, req Request) []Result {
	return r.CallExcept(ctx, req, nil)
}

// CallExcept is Call without the providers skip reports true for (e.g.
// those that already failed during the same answer).
func (r *Registry) CallExcept(ctx context.Context, req Request, skip func(provider string) bool) []Result {
	ps := r.For(req.Capability)
	if skip != nil {
		ps = slices.DeleteFunc(ps, func(p Provider) bool { return skip(p.Name()) })
	}
	results := make([]Result, len(ps))
	var wg sync.WaitGroup
	for i, p := range ps {
		wg.Add(1)
		go func() {
			defer wg.Done()
			results[i] = r.callOne(ctx, p, req)
		}()
	}
	wg.Wait()

	r.mu.Lock()
	observe, skip := r.observe, r.skipPath
	r.mu.Unlock()
	if skip != nil {
		for i := range results {
			kept := results[i].Items[:0]
			for _, it := range results[i].Items {
				if it.Path == "" || !skip(it.Path) {
					kept = append(kept, it)
				}
			}
			results[i].Items = kept
		}
	}
	if observe != nil {
		for _, res := range results {
			observe(res, req)
		}
	}
	return results
}

func (r *Registry) callOne(ctx context.Context, p Provider, req Request) (res Result) {
	ctx, cancel := context.WithTimeout(ctx, r.timeout)
	defer cancel()
	start := time.Now()
	defer func() {
		if v := recover(); v != nil {
			res = Result{Err: &Error{Provider: p.Name(), Message: fmt.Sprintf("internal panic: %v", v)}}
		}
		res.Provider, res.Capability = p.Name(), req.Capability
		res.Latency = time.Since(start)
		if errors.Is(ctx.Err(), context.DeadlineExceeded) {
			res.TimedOut = true
		}
		if res.Err == nil && ctx.Err() != nil {
			res.Err = &Error{Provider: p.Name(), Message: "timed out after " + r.timeout.String()}
		}
	}()
	out, err := p.Do(ctx, req)
	if err != nil {
		out.Err = err
	}
	return out
}

// Overview asks every provider offering project.overview for the
// project's structure: per provider its summary, and one line per error.
// skip leaves a provider out (e.g. an index built on another branch).
func (r *Registry) Overview(ctx context.Context, skip func(provider string) bool) (map[string]map[string]any, []string) {
	var structure map[string]map[string]any
	var errs []string
	for _, res := range r.Call(ctx, Request{Capability: Overview}) {
		if skip != nil && skip(res.Provider) {
			continue
		}
		if res.Err != nil {
			msg, _, _ := strings.Cut(res.Err.Error(), "\n")
			errs = append(errs, msg)
			continue
		}
		if structure == nil {
			structure = map[string]map[string]any{}
		}
		structure[res.Provider] = res.Summary
	}
	return structure, errs
}

// IndexedProviders names the providers whose answers come from an index.
func (r *Registry) IndexedProviders() map[string]bool {
	out := map[string]bool{}
	for _, c := range r.Capabilities() {
		if c.Freshness == Indexed {
			out[c.Provider] = true
		}
	}
	return out
}

// Warm asks every provider for its capabilities in the background. That
// starts harness protocol providers early (a provider not used in this
// project offers nothing and starts nothing; generic MCP providers declare
// theirs without starting), so slow warm-ups such as graphify's compiled
// solution begin when the server starts, not on the first query.
func (r *Registry) Warm() {
	for _, p := range r.Providers() {
		go p.Capabilities()
	}
}

// Close closes every provider, returning the first error.
func (r *Registry) Close() error {
	var first error
	for _, p := range r.Providers() {
		if err := p.Close(); err != nil && first == nil {
			first = err
		}
	}
	return first
}

// Refresher is implemented by providers that keep their own index of the
// project and can bring it up to date after files change. Live providers
// (reading the working tree on every call) do not implement it.
type Refresher interface {
	Provider
	Refresh(ctx context.Context, req RefreshRequest) (RefreshResult, error)
}

// RefreshRequest describes what changed since the provider's last refresh.
type RefreshRequest struct {
	// Full asks for a complete rebuild (full sync, branch switch).
	Full bool
	// Changed lists changed paths relative to the project root
	// (added, modified, deleted or renamed).
	Changed []string
}

// RefreshResult reports what a refresh did.
type RefreshResult struct {
	Skipped bool   // nothing done (e.g. the project is not indexed by this provider)
	Detail  string // human-readable summary
}

// Versioned is implemented by providers that know the version of the
// server behind them once it runs ("" before).
type Versioned interface {
	ServerVersion() string
}
